'use strict';
/* Leads & pipeline group: /leads, /seller-leads, /leads-pipeline, /on-market-pipeline, /off-market-pipeline,
   /appraisal-submissions, /database, /prospects, /garage-sales. Prefix cwLd. */
const CW_LD_TABS=[['enquiries','Buyer Enquiries','Buyer Enquiry'],['offers','Offers',null],['inspections','Inspection Requests','Inspection Request'],['renters','Renter Enquiries','Renter Enquiry'],['applications','Agent Applications','Agent Application'],['ignored','Ignored',null]];
const CW_LD_SOURCES=['realestate.com.au','Form','Buyer Portal','Chatbot','Website','Referral','Direct Contact','Domain','Facebook recruitment ad'];
const CW_LD_STAGES=['New lead','Connected','Appraisal','Proposal','Authority','Listed','For sale','Sold','Lost'];
const CW_LD_PSTAGES=['New','Connected','Long Term','Appraisal','Listed','For Sale','Sold','Lost'];
const CW_LD_P2D={New:'New lead',Connected:'Connected',Appraisal:'Appraisal',Listed:'Listed','For Sale':'For sale',Sold:'Sold',Lost:'Lost'};
const CW_LD_COMPLIANCE=()=>({'Signed sales authority':false,'Property Price Statement':false,'Pricing / comparable-sales evidence':false,'Contract of Sale + Section 32':false,'Due diligence checklist available':false});

function cwLdEnsure(){
 for(const d of state.deals){const x=cwDX(d);if(!x.ldInit){x.ldInit=true;if(['New lead','Connected'].includes(d.stage))x.market=cwHash(d.id)%3?'Off market':'On market';x.timeframe=x.timeframe||cwPick(d.id+'tf',['0 to 3 months','3 to 6 months','6 to 12 months','Unsure']);x.apprCol=x.apprCol||(d.stage==='Appraisal'?'New / Unassigned':d.stage==='Lost'?'Lost':(x.temp||'Warm'))}}
 if(!state.cw.dbCats)state.cw.dbCats=[];
 if(!state.cw.ldUploads)state.cw.ldUploads=[];
}
function cwLdNewDeal(o){const id='D-'+(3000+state.deals.length)+Math.random().toString(10).slice(2,4);
 const d={id,legacyId:'NEW',contactId:o.contactId,propertyId:'P-'+id,address:o.address,suburb:o.suburb||'',state:'VIC',postcode:CW_POSTCODES[o.suburb]||'',stage:o.stage||'New lead',guide:Number(o.guide)||0,fee:1.85,owner:CW_ME,source:o.source||'Website',why:o.why||'New seller lead',next:o.next||'Call seller',risk:'',compliance:CW_LD_COMPLIANCE(),lastChange:'Just now',buyerMatches:0,active:o.stage!=='Lost'&&o.stage!=='Sold'};
 state.deals.push(d);cwDX(d);d.cw.ldInit=true;Object.assign(d.cw,o.cw||{});cwPropActivity(d,'Record created'+(o.via?' from '+o.via:''));audit('property','Property record created: '+d.address,o.via||'Added in the CRM pages');return d}
function cwLdWho(p,extra=''){return p?`<div class="cw-who">${cwAvatar(p.name)}<div><b>${cwLink(h(p.name),'/contacts/'+p.id,'table-btn')}</b><small>${h(p.phone||'')}${p.email?' · '+h(p.email):''}${extra}</small></div></div>`:'<span class="muted">No contact</span>'}
function cwLdInRange(iso,r){if(!r||r==='All time')return true;const days={Today:1,'Last 7 days':7,'Last 30 days':30,'Last 90 days':90}[r]||9999;if(r==='Today')return cwLocalDay(iso)===cwLocalDay();return Date.parse(iso)>=Date.now()-days*864e5}
function cwLdStageSelect(d,attr,stages,cur){return `<select class="field cw-mini" data-${attr}="${h(d.id)}" aria-label="Stage for ${h(d.address)}">${stages.map(s=>`<option ${s===cur?'selected':''}>${h(s)}</option>`).join('')}</select>`}
function cwLdSetStage(d,stage,why){if(!d||d.stage===stage)return;const from=d.stage;d.stage=stage;d.active=!['Sold','Lost'].includes(stage);d.lastChange='Just now';cwDX(d).status=CW_STAGE_TO_STATUS[stage]||cwDX(d).status;cwPropActivity(d,'Stage changed from '+from+' to '+stage+(why?' ('+why+')':''));audit('pipeline',d.address+' moved to '+stage,'From '+from+'. '+(why||'Changed in the CRM pages.'))}

/* ---------- /leads ---------- */
function cwLdEnqRows(tab){const showP=cwF('cwLd:proc',false),mine=cwF('cwLd:mine','mine')==='mine',type=cwF('cwLd:type','All Types'),rng=cwF('cwLd:range','All time'),prop=cwF('cwLd:prop','All Properties'),ag=cwF('cwLd:agent','All Agents'),src=cwF('cwLd:src','All Sources');
 const def=CW_LD_TABS.find(t=>t[0]===tab);
 return state.cw.enquiries.filter(e=>{if(tab==='ignored'){if(e.status!=='Ignored')return false}else{if(e.status==='Ignored')return false;if(def?.[2]&&e.type!==def[2])return false;if(!showP&&e.status==='Processed')return false}
  if(tab!=='applications'&&mine&&e.agent!==CW_ME)return false;if(type!=='All Types'&&e.type!==type)return false;if(!cwLdInRange(e.received,rng))return false;if(prop!=='All Properties'&&e.dealId!==prop)return false;if(ag!=='All Agents'&&e.agent!==ag)return false;if(src!=='All Sources'&&e.source!==src)return false;return true}).sort((a,b)=>Date.parse(b.received)-Date.parse(a.received))}
cwPage('/leads',{title:'Enquiries & offers',group:'leads',render(ctx){cwLdEnsure();
 const tab=CW_LD_TABS.some(t=>t[0]===ctx.q.tab)?ctx.q.tab:'enquiries';
 const counts=Object.fromEntries(CW_LD_TABS.map(([k,,t])=>[k,k==='offers'?(state.offers||[]).filter(o=>o.status==='New').length:k==='ignored'?state.cw.enquiries.filter(e=>e.status==='Ignored').length:state.cw.enquiries.filter(e=>e.type===t&&e.status==='Pending').length]));
 const isApp=tab==='applications';
 const head=cwHeader(isApp?'Agent Applications':'Buyer Enquiries & Offers',isApp?'Agent applications from the Facebook recruitment ads. Visible to admins only.':'Review and qualify buyer enquiries and offers. Assign them to properties, or ignore to move them to the Ignored tab. Ignoring never deletes a contact.',`${isApp?'':cwPills('cwLd:mine',[['mine','My enquiries'],['all','All agents']])}${cwBtn(ico('refresh','sm')+' Refresh enquiries','cwLdRefresh','','')}`);
 const tabs=cwTabs('cwLdTab',CW_LD_TABS.map(([k,l])=>[k,l,counts[k]]),{active:tab,route:v=>'/leads?tab='+v});
 const props=[['All Properties','All Properties'],...cwProps().filter(d=>state.cw.enquiries.some(e=>e.dealId===d.id)).map(d=>[d.id,cwAddr(d)])];
 const filters=`<div class="toolbar">${cwSelect('cwLd:type',['All Types','Buyer Enquiry','Inspection Request','Renter Enquiry','Agent Application'],{label:'Type'})}${cwSelect('cwLd:range',['All time','Today','Last 7 days','Last 30 days','Last 90 days'],{label:'Date range'})}${cwSelect('cwLd:prop',props,{label:'Property'})}${cwSelect('cwLd:agent',['All Agents',...cwAgentNames()],{label:'Agent'})}${cwSelect('cwLd:src',['All Sources',...CW_LD_SOURCES],{label:'Source'})}${cwCheck('cwLd:proc','Show processed')}</div>`;
 if(tab==='offers'){const offers=(state.offers||[]).slice().sort((a,b)=>(a.status==='New'?0:1)-(b.status==='New'?0:1));
  return head+tabs+cwTable('cwLdOffers',[['Property',o=>{const d=findD(o.dealId);return d?cwLink(h(d.address+', '+d.suburb),'/properties/'+d.id):''},o=>findD(o.dealId)?.address||''],['Buyer',o=>cwLdWho(findP(o.buyerId)),o=>personName(o.buyerId)],['Offer',o=>`<b>${cwMoney(o.amount)}</b><div class="tiny muted">Guide when received ${cwMoney(o.guideAtReceipt)}</div>`,o=>o.amount],['Terms',o=>`<span class="small">${h(o.deposit||'')} deposit · ${h(o.finance||'')} · ${h(o.settlement||'')}</span>`],['Vendor',o=>h(personName(o.vendorId))],['Status',o=>tag(o.status,o.status==='New'?'red':'')],['',o=>`<div class="cw-row">${o.status==='New'?cwBtn('Review on Today','route','today','sm primary'):''}${cwBtn('Notes','cwLdNotes','offer|'+o.id,'sm')}${cwGoBtn('Property','/properties/'+o.dealId+'?tab=enquiries','sm')}</div>`]],offers,{key:o=>o.id,empty:'All clear!',emptyBody:'No pending offers. Offers submitted via the Buyer Portal will appear here.'})}
 const rows=cwLdEnqRows(tab);
 const emptyMap={enquiries:'No pending buyer enquiries.',inspections:'No pending inspection requests. Buyer Portal inspection registrations will appear here.',renters:'No pending renter enquiries. Enquiries on rental listings will appear here.',applications:'No agent applications yet. Enquiries from the Facebook recruitment ads land here.',ignored:'Nothing ignored. Anything you ignore lands here and can be restored.'};
 return head+tabs+filters+cwTable('cwLdEnq'+tab,[
  ['Received',e=>`<span class="small">${cwDateTime(e.received)}</span>`,e=>e.received],
  ['Type',e=>tag(e.type,e.type==='Buyer Enquiry'?'teal':e.type==='Inspection Request'?'green':e.type==='Agent Application'?'purple':'')],
  ['Name',e=>e.contactId?cwLdWho(findP(e.contactId)):`<b>${h(e.name||'')}</b><div class="tiny muted">${h(e.phone||'')} ${h(e.email||'')}</div>`,e=>e.contactId?personName(e.contactId):e.name],
  ['Property',e=>{const d=findD(e.dealId);return d?cwLink(h(d.address+', '+d.suburb),'/properties/'+d.id):'<span class="muted">Not linked</span>'}],
  ['Agent',e=>h(e.agent||'')],
  ['Price',e=>{const d=findD(e.dealId);return d?cwPrice(d):''}],
  ['Source',e=>tag(e.source,'outline')],
  ['Status',e=>tag(e.status==='Pending'?'Pending/Unprocessed':e.status,e.status==='Pending'?'yellow':e.status==='Processed'?'green':'')],
  ['Comments',e=>`<span class="small clip" style="display:block;max-width:220px">${h(e.comments||'')}</span>`],
  ['Actions',e=>`<div class="cw-row">${cwBtn('View','cwLdView',e.id,'sm')}${e.contactId?cwBtn('Add to Property','cwLdAddProp',e.id,'sm')+cwBtn('Buying Preferences','cwLdPrefs',e.contactId,'sm'):''}${cwBtn('Notes','cwLdNotes','enq|'+e.id,'sm')}${e.status==='Ignored'?cwBtn('Restore','cwLdRestore',e.id,'sm primary'):e.status==='Pending'?cwBtn('Processed','cwLdProcess',e.id,'sm')+cwBtn('Ignore','cwLdIgnore',e.id,'sm ghost'):cwBtn('Reopen','cwLdRestore',e.id,'sm')}</div>`]
 ],rows,{select:tab!=='ignored',empty:'All clear!',emptyBody:emptyMap[tab]||'',bulk:()=>cwBtn('Mark processed','cwLdBulkProc','cwLdEnq'+tab,'sm')+cwBtn('Ignore','cwLdBulkIgnore','cwLdEnq'+tab,'sm')})},
 ai(ctx){cwLdEnsure();const pend=state.cw.enquiries.filter(e=>e.status==='Pending'&&e.type==='Buyer Enquiry');
  let auto=0,wait=[];for(const e of pend){const m=e.msgId?getMsg(e.msgId):null;if(m&&typeof gvxClassify==='function'){const c=gvxClassify(m);if(c.mode==='auto')auto++;else wait.push(c.reason)}}
  const draftable=pend.filter(e=>{const p=findP(e.contactId);return p&&!cwOptedOut(p)&&!state.actions.some(a=>a.cwLdEnq===e.id)});
  const offers=(state.offers||[]).filter(o=>o.status==='New');
  return[offers.length?{k:'check',t:offers.length+' written offers waiting',b:'Offers always wait for you and the vendor\'s instructions. They sit at the top of Today.',a:[['Open Today','route','today','primary']]}:null,
   {k:'auto',t:auto+' enquiries GeeVee can answer on its own',b:'Only replies where every fact comes from a verified record, such as an inspection time or a Section 32 on file.'},
   draftable.length?{k:'draft',t:'Draft replies to '+draftable.length+' buyers',b:'Each draft goes to Today for your approval. Opted-out contacts are skipped.'+(wait.length?' Why some wait: '+h(wait[0]):''),a:[['Draft replies','cwLdDraftReplies','','primary']]}:null,
   state.cw.enquiries.filter(e=>e.status==='Pending'&&!e.dealId&&e.contactId).length?{k:'info',t:'Enquiries without a property',b:'Link them so buyer matching and price checks work.'}:null]}});
cwOn('cwLdRefresh',()=>{audit('sync','Enquiries refreshed','Checked portals, website and Buyer Portal (simulated).');cwPersist('Enquiries are up to date.')});
cwOn('cwLdView',id=>cwModal('cwLdView',id));
cwModalDef('cwLdView',id=>{const e=state.cw.enquiries.find(x=>x.id===id);if(!e)return{title:'Enquiry',body:'<p>Not found.</p>'};const p=findP(e.contactId),d=findD(e.dealId),m=e.msgId?getMsg(e.msgId):null;
 return{title:e.type+(p?' from '+p.name:e.name?' from '+e.name:''),wide:'large',body:`${cwKV([['Received',cwDateTime(e.received)],['Source',h(e.source)],['Agent',h(e.agent)],['Status',h(e.status)],['Property',d?h(cwAddr(d)):''],['Price',d?cwPrice(d):''],['Phone',h(p?.phone||e.phone||'')],['Email',h(p?.email||e.email||'')]])}<div class="sep"></div><h3>Message</h3><p class="small" style="white-space:pre-wrap;margin-top:6px">${h(e.comments||'')}</p>${m&&typeof gvxClassify==='function'?`<div class="sep"></div>${cwNote('<b>GeeVee:</b> '+h(gvxClassify(m).mode==='auto'?'Can answer this from verified records.':gvxClassify(m).reason||'Waits for you.'))}`:''}${(e.notes||[]).length?`<div class="sep"></div><h3>Notes</h3>${e.notes.map(n=>`<p class="small">${h(n.text)} <span class="muted">${cwDateTime(n.at)}</span></p>`).join('')}`:''}`,
  foot:`${p?cwGoBtn('Open contact','/contacts/'+p.id,''):''}${m?cwBtn('Open conversation','personMessages',p?.id||'',''):''}${p&&!cwOptedOut(p)?cwBtn('Call','call',p.id,''):''}${cwBtn('Close','close','','primary')}`}});
cwOn('cwLdAddProp',id=>cwModal('cwLdAddProp',id));
cwModalDef('cwLdAddProp',id=>{const e=state.cw.enquiries.find(x=>x.id===id);return{title:'Add to property',body:`<p class="small" style="margin-bottom:10px">Link ${h(personName(e?.contactId))} to a property. The enquiry shows on the property's Enquiries tab and feeds buyer matching.</p>${cwForm('cwLdAP',[{n:'dealId',l:'Property',t:'select',req:true,o:[['','Choose a property'],...cwProps().filter(d=>d.active).map(d=>[d.id,cwAddr(d)])]}],{dealId:e?.dealId||''})}`,foot:cwBtn('Cancel','close')+cwBtn('Link property','cwLdAddPropSave',id,'primary')}});
cwOn('cwLdAddPropSave',id=>{const v=cwRead('cwLdAP',[{n:'dealId',l:'Property',t:'select',req:true}]);if(!v)return;const e=state.cw.enquiries.find(x=>x.id===id),d=findD(v.dealId),p=findP(e?.contactId);if(!e||!d)return;e.dealId=d.id;if(p){const x=cwPX(p);if(!x.linked.includes(d.id))x.linked.push(d.id);cwContactHistory(p,'Linked to '+d.address+' from an enquiry')}cwPropActivity(d,'Enquiry from '+(p?.name||'a buyer')+' linked');ui.modal=null;cwPersist('Enquiry linked to '+d.address+'.')});
const CW_LD_PREF_FIELDS=[{n:'suburbs',l:'Suburbs (comma separated)',full:true},{n:'priceMin',l:'Price from ($)',t:'number'},{n:'priceMax',l:'Price to ($)',t:'number'},{n:'beds',l:'Bedrooms (minimum)',t:'number'},{n:'baths',l:'Bathrooms (minimum)',t:'number'},{n:'cars',l:'Car spaces (minimum)',t:'number'},{n:'types',l:'Property types',t:'select',o:['House','Townhouse','Unit','Apartment','Land','Any']},{n:'intent',l:'Buying intent',t:'select',o:['cold','warm','active','hot','priority']}];
cwOn('cwLdPrefs',id=>cwModal('cwLdPrefs',id));
cwModalDef('cwLdPrefs',id=>{const p=findP(id),x=cwPX(p),pr=x?.prefs||{};return{title:'Buying preferences: '+(p?.name||''),body:cwForm('cwLdPr',CW_LD_PREF_FIELDS,{...pr,suburbs:(pr.suburbs||[]).join(', '),types:(pr.types||[])[0]||'House'}),foot:cwBtn('Cancel','close')+cwBtn('Save preferences','cwLdPrefsSave',id,'primary')}});
cwOn('cwLdPrefsSave',id=>{const v=cwRead('cwLdPr',CW_LD_PREF_FIELDS);if(!v)return;const p=findP(id);if(!p)return;const x=cwPX(p);x.prefs={...(x.prefs||{}),suburbs:v.suburbs.split(',').map(s=>s.trim()).filter(Boolean),priceMin:Number(v.priceMin)||0,priceMax:Number(v.priceMax)||0,beds:Number(v.beds)||0,baths:Number(v.baths)||0,cars:Number(v.cars)||0,types:[v.types],intent:v.intent};cwContactHistory(p,'Buying preferences updated');ui.modal=null;cwPersist('Preferences saved. Buyer matching uses them straight away.')});
cwOn('cwLdNotes',id=>cwModal('cwLdNotes',id));
cwModalDef('cwLdNotes',key=>{const [kind,id]=key.split('|');const rec=kind==='offer'?(state.offers||[]).find(o=>o.id===id):state.cw.enquiries.find(e=>e.id===id);const notes=rec?.notes||[];
 return{title:'Notes',body:`${notes.map(n=>`<div class="cw-tl"><span class="cw-tl-dot"></span><div><b>${h(n.by)}</b><small>${cwDateTime(n.at)}</small><p>${h(n.text)}</p></div></div>`).join('')||'<p class="hint">No notes yet.</p>'}<div class="sep"></div>${cwForm('cwLdN',[{n:'text',l:'Add a note',t:'textarea',req:true}])}`,foot:cwBtn('Close','close')+cwBtn('Save note','cwLdNoteSave',key,'primary')}});
cwOn('cwLdNoteSave',key=>{const v=cwRead('cwLdN',[{n:'text',l:'Note',t:'textarea',req:true}]);if(!v)return;const [kind,id]=key.split('|');const rec=kind==='offer'?(state.offers||[]).find(o=>o.id===id):state.cw.enquiries.find(e=>e.id===id);if(!rec)return;(rec.notes=rec.notes||[]).unshift({text:v.text,by:CW_ME,at:cwNowISO()});const p=findP(rec.contactId||rec.buyerId);if(p)cwPX(p).notes.unshift({id:cwId('CN'),text:v.text,kind:kind==='offer'?'Offer':'Enquiry',by:CW_ME,at:cwNowISO()});cwPersist('Note saved.');cwModal('cwLdNotes',key)});
cwOn('cwLdIgnore',id=>{const e=state.cw.enquiries.find(x=>x.id===id);if(!e)return;e.status='Ignored';audit('enquiry','Enquiry ignored','The contact is kept. Restore it from the Ignored tab.');cwPersist('Moved to Ignored. The contact is kept.')});
cwOn('cwLdRestore',id=>{const e=state.cw.enquiries.find(x=>x.id===id);if(!e)return;e.status='Pending';cwPersist('Enquiry restored.')});
cwOn('cwLdProcess',id=>{const e=state.cw.enquiries.find(x=>x.id===id);if(!e)return;e.status='Processed';audit('enquiry','Enquiry processed: '+(e.contactId?personName(e.contactId):e.name),e.type);cwPersist('Marked processed.')});
cwOn('cwLdBulkProc',k=>{const s=cwSel(k);state.cw.enquiries.filter(e=>s.includes(e.id)).forEach(e=>e.status='Processed');cwU().sel[k]=[];cwPersist(s.length+' marked processed.')});
cwOn('cwLdBulkIgnore',k=>{const s=cwSel(k);state.cw.enquiries.filter(e=>s.includes(e.id)).forEach(e=>e.status='Ignored');cwU().sel[k]=[];cwPersist(s.length+' moved to Ignored.')});
cwOn('cwLdDraftReplies',()=>{let n=0;for(const e of state.cw.enquiries.filter(e=>e.status==='Pending'&&e.type==='Buyer Enquiry')){const p=findP(e.contactId),d=findD(e.dealId);if(!p||cwOptedOut(p)||state.actions.some(a=>a.cwLdEnq===e.id))continue;const first=p.name.split(' ')[0];addAction({type:'SMS',title:'Reply to '+p.name+' about '+(d?d.address:'their enquiry'),body:`Hi ${first}, thanks for your enquiry${d?' about '+d.address+', '+d.suburb:''}. I'll call you today to answer your question properly. Caleb, Collings. Reply STOP to opt out.`,contactId:p.id,dealId:d?.id||'',tier:'A2',cwLdEnq:e.id});n++}cwPersist(n?n+' drafts are on Today for your approval. Nothing was sent.':'No new drafts needed.')});

