 if(el.dataset.cwldmarket){const d=findD(el.dataset.cwldmarket);if(!d)return;cwDX(d).market=el.value;persist();render();return}
 if(el.dataset.cwldtemp){const d=findD(el.dataset.cwldtemp);if(!d)return;cwDX(d).temp=el.value==='Unsorted'?'':el.value;persist();render();return}
