 const src=cwF('cwLd:lpsrc','All Sources'),pri=cwF('cwLd:lppri','All Priorities'),stg=cwF('cwLd:lpstg','All Stages'),settle=cwF('cwLd:lpset','All Settlement Dates'),q=cwF('cwLd:lpq','');
