const CW_LD_COLOURS=['Red','Orange','Yellow','Green','Teal','Blue','Purple'];
function cwLdDbRows(){const r=state.cw.db.records,cat=cwF('cwLd:dbcat','All'),sub=cwF('cwLd:dbsub','Suburb: any'),beds=cwF('cwLd:dbbeds','Beds: any'),temp=cwF('cwLd:dbtemp','Temp: any'),col=cwF('cwLd:dbcol','Colour: any'),dnc=cwF('cwLd:dbdnc','Do not contact: any'),perm=cwF('cwLd:dbperm','Permission: any'),mkt=cwF('cwLd:dbmkt','Market: any'),q=cwF('cwLd:dbq','');
 let list=r.filter(x=>(x.list||'Owners')==='Owners');
 if(cat==='In pipeline')list=list.filter(x=>x.dealId);else if(cat==='Appraisals only')list=list.filter(x=>x.dealId&&['Appraisal','Proposal','Authority'].includes(findD(x.dealId)?.stage));else if(cat==='Callbacks due')list=list.filter(x=>x.nextCall&&x.nextCall<=cwLocalDay());else if(cat!=='All')list=list.filter(x=>x.cat===cat);
 if(sub!=='Suburb: any')list=list.filter(x=>x.suburb===sub);if(beds!=='Beds: any')list=list.filter(x=>String(x.beds)===beds);if(temp!=='Temp: any')list=list.filter(x=>x.temp===temp);if(col!=='Colour: any')list=list.filter(x=>(x.colour||'').toLowerCase()===col.toLowerCase());
 if(dnc==='Only unsubscribed')list=list.filter(x=>x.dnc);if(dnc==='Hide unsubscribed')list=list.filter(x=>!x.dnc);if(perm!=='Permission: any')list=list.filter(x=>x.permission===perm);if(mkt!=='Market: any')list=list.filter(x=>mkt==='For sale or withdrawn'?['For sale','Withdrawn'].includes(x.market):x.market===mkt);
 return cwSearchRows(list,q,x=>x.address+' '+x.suburb+' '+x.owner+' '+x.mobile)}
