cwModalDef('cwLdCsv',()=>({title:'Upload CSV',body:`<p class="small" style="margin-bottom:10px">Columns read: address, suburb, type, beds, baths, owner, mobile, email. Rows without an address are skipped. Uploads are checked for duplicates by address.</p><input type="file" accept=".csv,text/csv" id="cwLdCsvFile" class="field full" aria-label="CSV file">`,foot:cwBtn('Cancel','close')+cwBtn('Upload','cwLdCsvGo','','primary')}));
cwOn('cwLdCsvGo',()=>{const f=document.getElementById('cwLdCsvFile')?.files?.[0];if(!f){toast('Choose a CSV file first.');return}const rd=new FileReader();rd.onload=()=>{const lines=String(rd.result).split(/\r?\n/).filter(l=>l.trim());if(lines.length<2){toast('That file has no data rows.');return}const head=lines[0].split(',').map(s=>s.trim().toLowerCase());const col=n=>head.indexOf(n);const up=cwId('UP');let n=0,dup=0;
  for(const l of lines.slice(1)){const c=l.split(',').map(s=>s.trim().replace(/^"|"$/g,''));const address=c[col('address')]||'';if(!address)continue;if(state.cw.db.records.some(x=>x.address.toLowerCase()===address.toLowerCase())){dup++;continue}state.cw.db.records.unshift({id:cwId('DB'),list:'Owners',colour:'',address,suburb:c[col('suburb')]||'',type:c[col('type')]||'House',beds:Number(c[col('beds')])||0,baths:Number(c[col('baths')])||0,land:'',lastSold:'',owner:c[col('owner')]||'Unknown owner',mobile:c[col('mobile')]||'',email:c[col('email')]||'',owner2:'',mobile2:'',email2:'',temp:'Cold',looking:'Unknown',nextCall:'',lastNote:'Uploaded from '+f.name,dnc:false,permission:'No evidence',market:'',upload:up});n++}
  state.cw.ldUploads.push({id:up,name:f.name,at:cwNowISO(),n});audit('database','CSV uploaded: '+f.name,n+' records added, '+dup+' duplicates skipped.');ui.modal=null;cwPersist(n+' records added from '+f.name+(dup?', '+dup+' duplicates skipped':'')+'.')};rd.readAsText(f)});
cwOn('cwLdCsvUndo',()=>{const u=state.cw.ldUploads.pop();if(!u)return;state.cw.db.records=state.cw.db.records.filter(x=>x.upload!==u.id);cwPersist('Upload '+u.name+' removed ('+u.n+' records).')});

/* ---------- /prospects ---------- */
function cwLdPStage(d){return cwDX(d).longTerm?'Long Term':CW_PROSPECT_STAGE[d.stage]||'New'}
function cwLdProspects(){const mk=cwF('cwLd:pmkt','All markets'),ag=cwF('cwLd:pag','All agents'),st=cwF('cwLd:pst','');let ds=cwProps().filter(d=>d.contactId&&['seller','both'].includes(findP(d.contactId)?.role));
 if(mk!=='All markets')ds=ds.filter(d=>cwDX(d).market===mk);if(ag!=='All agents')ds=ds.filter(d=>(cwDX(d).agents[0]||CW_ME)===ag);
 if(st==='At risk')ds=ds.filter(d=>d.risk);else if(st)ds=ds.filter(d=>cwLdPStage(d)===st);return ds}
function cwLdPCard(d){const x=cwDX(d),p=findP(d.contactId);return `<div class="pipe-card"><h3>${h(p?.name||'No owner on file')}</h3><div class="sub">${h(d.address)}, ${h(d.suburb)}</div><div class="money">${d.guide?cwShort(d.guide):'Price not set'}</div><div class="cw-row" style="gap:4px;margin-bottom:6px">${tag(d.source,'outline')}${d.risk?tag(d.risk,'red'):''}</div><select class="field cw-mini" data-cwldpstage="${h(d.id)}" aria-label="Stage for ${h(d.address)}">${CW_LD_PSTAGES.map(s=>`<option ${s===cwLdPStage(d)?'selected':''}>${s}</option>`).join('')}</select> <select class="field cw-mini" data-cwldmarket="${h(d.id)}" aria-label="Market for ${h(p?.name||d.address)}">${['Off market','On market'].map(s=>`<option ${s===x.market?'selected':''}>${s}</option>`).join('')}</select> <select class="field cw-mini" data-cwldtemp="${h(d.id)}" aria-label="Temperature for ${h(d.address)}">${['Unsorted','Hot','Warm','Cold'].map(s=>`<option ${s===(x.temp||'Unsorted')?'selected':''}>${s}</option>`).join('')}</select><div class="cw-row" style="gap:4px;margin-top:6px">${cwBtn('Call','call',d.contactId,'sm primary')}${cwBtn('Notes','cwLdSlNotes',d.id,'sm')}${cwBtn('Open','openDeal',d.id,'sm')}</div></div>`}
cwPage('/prospects',{title:'Prospects',group:'leads',wide:true,render(){cwLdEnsure();
 const tab=cwTab('cwLdPr','Pipeline'),ds=cwLdProspects(),all=cwProps();
 const cnt=s=>all.filter(d=>cwLdPStage(d)===s).length;
 const head=cwHeader('Prospects','One workspace for every seller lead, from raw contact through to sale. Toggle between your working pipeline and your contact Database.',`${cwBtn('Import','cwLdCsv','','')}${cwBtn('Export','cwLdExport','','')}${cwBtn('Add lead','cwLdLeadNew','','primary')}`);
 const stats=`<div class="toolbar">${cwPills('cwLd:pst',[['','Total leads',all.length],['New','New',cnt('New')],['At risk','At risk',all.filter(d=>d.risk).length],['Listed','Listed',cnt('Listed')],['For Sale','For Sale',cnt('For Sale')],['Lost','Lost',cnt('Lost')]])}</div><div class="toolbar">${cwTabs('cwLdPr',[['Pipeline','Pipeline',cnt('New')+' new'],['Database','Database'],['Kanban','Kanban'],['List','List']])}${cwSelect('cwLd:pmkt',['All markets','Off market','On market'],{label:'Market'})}${cwSelect('cwLd:pag',['All agents',...cwAgentNames()],{label:'Agent'})}${cwGoBtn('Buyer Match','/prospecting/find-buyers','sm')}${cwBtn(ico('refresh','sm')+' Refresh','cwLdRefresh','','sm')}</div>`;
 if(tab==='Database')return head+stats+cwNote('These are owners in your Database who are not in the pipeline yet. Add one to start working it.')+cwTable('cwLdPrDb',[['Owner',x=>`<b>${h(x.owner||'No owner on file')}</b>`,x=>x.owner],['Address',x=>h(x.address+', '+x.suburb)],['Mobile',x=>x.mobile?h(x.mobile):'<span class="muted">No mobile on file</span>'],['Email',x=>x.email?h(x.email):'<span class="muted">No email on file</span>'],['Temp',x=>tag(x.temp,x.temp==='Hot'?'hot':'')],['',x=>x.dealId?cwLink('In pipeline','/properties/'+x.dealId):cwBtn('Add to pipeline','cwLdDbPipe',x.id,'sm primary')]],state.cw.db.records.filter(x=>!x.dealId),{empty:'Nothing here yet'});
 if(tab==='List')return head+stats+cwTable('cwLdPrL',[['Owner',d=>cwLdWho(findP(d.contactId)),d=>personName(d.contactId)],['Property',d=>cwLink(h(d.address+', '+d.suburb),'/properties/'+d.id),d=>d.address],['Stage',d=>tag(cwLdPStage(d),'teal'),d=>CW_LD_PSTAGES.indexOf(cwLdPStage(d))],['Market',d=>h(cwDX(d).market)],['Temp',d=>tag(cwDX(d).temp||'Unsorted')],['Price',d=>d.guide?cwShort(d.guide):'',d=>d.guide],['Source',d=>h(d.source)],['',d=>cwBtn('Call','call',d.contactId,'sm')+' '+cwBtn('Open','openDeal',d.id,'sm')]],ds,{empty:'Nothing here yet'});
 const cols=CW_LD_PSTAGES.map(s=>({id:s,name:s,items:ds.filter(d=>cwLdPStage(d)===s),sub:cwShort(ds.filter(d=>cwLdPStage(d)===s).reduce((a,d)=>a+d.guide,0))}));
 if(tab==='Kanban')return head+stats+cwKanban(cols,cwLdPCard);
 const active=cols.filter(c=>!['Sold','Lost'].includes(c.id));
 return head+stats+active.map(c=>c.items.length?cwCard(h(c.name)+' '+tag(c.items.length+'','teal'),`<div class="cw-cards">${c.items.map(cwLdPCard).join('')}</div>`):'').join('')||cwEmpty('Nothing here yet')},
 ai(){const ds=cwProps().filter(d=>['New lead'].includes(d.stage));const noTemp=cwProps().filter(d=>d.active&&!cwDX(d).temp);return[ds.length?{k:'call',t:ds.length+' new prospects',b:'Call each new seller prospect. GeeVee prepares the brief, not a message.',a:[['Add call briefs','cwLdBriefs','','primary']]}:null,noTemp.length?{k:'check',t:noTemp.length+' prospects unsorted',b:'Set Hot, Warm or Cold so GeeVee ranks your follow-ups.'}:null,{k:'info',t:'Export respects permissions',b:'Exports include the do-not-contact flag so no list leaves DOMA without it.'}]}});
cwOn('cwLdExport',()=>{const ds=cwLdProspects();const rows=[['Owner','Mobile','Email','Address','Suburb','Stage','Market','Temperature','Price','Source','Do not contact']];for(const d of ds){const p=findP(d.contactId);rows.push([p?.name||'',p?.phone||'',p?.email||'',d.address,d.suburb,cwLdPStage(d),cwDX(d).market,cwDX(d).temp||'',d.guide||'',d.source,p&&cwOptedOut(p)?'Yes':'No'])}
 const csv=rows.map(r=>r.map(c=>'"'+String(c).replace(/"/g,'""')+'"').join(',')).join('\n');try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='prospects.csv';document.body.appendChild(a);a.click();a.remove()}catch(e){}audit('export','Prospects exported',ds.length+' rows, includes do-not-contact flag.');cwPersist(ds.length+' prospects exported to prospects.csv.')});

/* ---------- /garage-sales ---------- */
cwPage('/garage-sales',{title:'Garage sales',group:'leads',render(){
 const tab=cwTab('cwLdGs','To Work'),sub=cwF('cwLd:gssub','All suburbs'),sig=cwF('cwLd:gssig','Any signal'),sort=cwF('cwLd:gssort','Best to work'),up=cwF('cwLd:gsup',false);
 const all=state.cw.garage;let list=all.filter(g=>g.status===tab&&(sub==='All suburbs'||g.suburb===sub)&&(sig==='Any signal'||g.signal===sig)&&(!up||Date.parse(g.date)>=Date.now()-864e5));
 const rank={'Looks like a mover':0,'Worth a look':1,'Ordinary clear-out':2};
 list.sort((a,b)=>sort==='Newest first'?Date.parse(b.date)-Date.parse(a.date):sort==='Oldest first'?Date.parse(a.date)-Date.parse(b.date):sort==='Coldest first'?rank[b.signal]-rank[a.signal]:rank[a.signal]-rank[b.signal]||Date.parse(a.date)-Date.parse(b.date));
 return `${cwHeader('Garage Sales','Local garage sales, sorted by how likely the owner is to move.',`${cwBtn('How this works','cwLdGsHow','','')}${cwBtn('Areas','cwLdGsAreas','','')}${cwBtn('Sync now','cwLdGsSync','','')}${cwBtn('Add a sale','cwLdGsNew','','primary')}`)}
 ${cwStats([['Likely movers',all.filter(g=>g.signal==='Looks like a mover'&&g.status==='To Work').length],['Upcoming',all.filter(g=>Date.parse(g.date)>=Date.now()).length],['Assigned',all.filter(g=>g.status==='Assigned').length],['Archived',all.filter(g=>g.status==='Archived').length]])}
 <div class="toolbar">${cwTabs('cwLdGs',['To Work','Assigned','Archived'].map(s=>[s,s,all.filter(g=>g.status===s).length]))}${cwSelect('cwLd:gssub',['All suburbs',...new Set(all.map(g=>g.suburb))],{label:'Suburb'})}${cwSelect('cwLd:gssig',['Any signal','Looks like a mover','Worth a look','Ordinary clear-out'],{label:'Signal'})}${cwSelect('cwLd:gssort',['Best to work','Hottest first','Coldest first','Newest first','Oldest first'],{label:'Sort'})}${cwCheck('cwLd:gsup','Upcoming only')}</div>
 ${cwTable('cwLdGsT',[['Address',g=>`<b>${h(g.address)}, ${h(g.suburb)}</b>`,g=>g.address],['Date',g=>cwDateTime(g.date),g=>g.date],['Signal',g=>tag(g.signal,g.signal==='Looks like a mover'?'hot':g.signal==='Worth a look'?'yellow':'')],['Listing text',g=>`<span class="small">${h(g.note)}</span>`],['Agent',g=>h(g.agent||'Unassigned')],['Owner',g=>{const r=state.cw.db.records.find(x=>x.address.toLowerCase()===g.address.toLowerCase());return r?h(r.owner):'<span class="muted">Not in Database</span>'}],['',g=>`<div class="cw-row">${g.status!=='Assigned'?cwBtn('Assign','cwLdGsAssign',g.id,'sm primary'):''}${g.status!=='Archived'?cwBtn('Archive','cwLdGsArch',g.id,'sm'):cwBtn('Restore','cwLdGsRestore',g.id,'sm')}${cwBtn('Add to Database','cwLdGsDb',g.id,'sm ghost')}</div>`]],list,{empty:'No garage sales here yet',emptyBody:'Sync now checks the listing sites for your areas.'})}`},
 ai(){const m=state.cw.garage.filter(g=>g.status==='To Work'&&g.signal==='Looks like a mover');return[m.length?{k:'check',t:m.length+' likely movers',b:m.map(g=>h(g.address)+': '+h(g.note)).join('<br>')+'<br>Visit or door knock. GeeVee sends nothing.',a:[['Assign to me','cwLdGsAssignMe','','primary']]}:{k:'info',t:'No likely movers right now'}]}});
cwOn('cwLdGsHow',()=>cwModal('cwLdGsHow'));
cwModalDef('cwLdGsHow',()=>({title:'How garage sales work',body:'<ul class="bullet small"><li>DOMA checks garage sale listings in your areas each morning.</li><li>Words like "moving", "downsizing" or "everything must go" mark a likely mover.</li><li>Assign a sale to an agent to visit or door knock. Nothing is sent to the owner.</li><li>Add the address to the Database to keep the owner on file once you have permission.</li></ul>',foot:cwBtn('Close','close','','primary')}));
cwOn('cwLdGsAreas',()=>cwModal('cwLdGsAreas'));
cwModalDef('cwLdGsAreas',()=>({title:'Areas to watch',body:cwForm('cwLdGA',[{n:'areas',l:'Suburbs (comma separated)',t:'textarea',req:true}],{areas:(state.cw.gsAreas||['Preston','Coburg','Thornbury']).join(', ')}),foot:cwBtn('Cancel','close')+cwBtn('Save areas','cwLdGsAreasSave','','primary')}));
cwOn('cwLdGsAreasSave',()=>{const v=cwRead('cwLdGA',[{n:'areas',l:'Areas',t:'textarea',req:true}]);if(!v)return;state.cw.gsAreas=v.areas.split(',').map(s=>s.trim()).filter(Boolean);ui.modal=null;cwPersist('Areas saved.')});
cwOn('cwLdGsSync',()=>{if(!state.cw.garage.some(g=>g.id==='GS-5')){state.cw.garage.unshift({id:'GS-5',address:'5 Penola Street',suburb:'Preston',date:cwDayISO(2,8),signal:'Looks like a mover',note:'"Moving to Queensland, everything goes"',status:'To Work',agent:''});cwPersist('1 new garage sale found.')}else cwPersist('No new garage sales.')});
const CW_LD_GS_FIELDS=[{n:'address',l:'Address',req:true},{n:'suburb',l:'Suburb',req:true},{n:'date',l:'Date',t:'date',req:true},{n:'signal',l:'Signal',t:'select',o:['Looks like a mover','Worth a look','Ordinary clear-out']},{n:'note',l:'Listing text',t:'textarea'}];
cwOn('cwLdGsNew',()=>cwModal('cwLdGsNew'));
cwModalDef('cwLdGsNew',()=>({title:'Add a sale',body:cwForm('cwLdGN',CW_LD_GS_FIELDS,{signal:'Worth a look'}),foot:cwBtn('Cancel','close')+cwBtn('Add sale','cwLdGsSave','','primary')}));
cwOn('cwLdGsSave',()=>{const v=cwRead('cwLdGN',CW_LD_GS_FIELDS);if(!v)return;state.cw.garage.unshift({id:cwId('GS'),...v,date:new Date(v.date+'T08:00').toISOString(),status:'To Work',agent:''});ui.modal=null;cwPersist('Sale added.')});
cwOn('cwLdGsAssign',id=>cwModal('cwLdGsAssign',id));
cwModalDef('cwLdGsAssign',id=>({title:'Assign garage sale',body:cwForm('cwLdGAs',[{n:'agent',l:'Agent',t:'select',o:cwAgentNames(),req:true}],{agent:CW_ME}),foot:cwBtn('Cancel','close')+cwBtn('Assign','cwLdGsAssignSave',id,'primary')}));
function cwLdGsDoAssign(g,agent){g.status='Assigned';g.agent=agent;if(agent===CW_ME&&!state.tasks.some(t=>t.cwLdGs===g.id))addTask({title:'Visit garage sale: '+g.address+', '+g.suburb,contactId:'',dealId:'',due:cwDate(g.date),dueISO:cwLocalDay(g.date),priority:g.signal==='Looks like a mover'?'High':'Normal',category:'Follow up',origin:'GeeVee · garage sale',cwLdGs:g.id})}
cwOn('cwLdGsAssignSave',id=>{const v=cwRead('cwLdGAs',[{n:'agent',l:'Agent',t:'select',req:true}]);if(!v)return;const g=state.cw.garage.find(x=>x.id===id);cwLdGsDoAssign(g,v.agent);ui.modal=null;cwPersist('Assigned to '+v.agent+'.')});
cwOn('cwLdGsAssignMe',()=>{const m=state.cw.garage.filter(g=>g.status==='To Work'&&g.signal==='Looks like a mover');m.forEach(g=>cwLdGsDoAssign(g,CW_ME));cwPersist(m.length+' assigned to you, visits added to Tasks.')});
cwOn('cwLdGsArch',id=>{const g=state.cw.garage.find(x=>x.id===id);if(g){g.status='Archived';cwPersist('Archived.')}});
cwOn('cwLdGsRestore',id=>{const g=state.cw.garage.find(x=>x.id===id);if(g){g.status='To Work';cwPersist('Restored to To Work.')}});
cwOn('cwLdGsDb',id=>{const g=state.cw.garage.find(x=>x.id===id);if(!g)return;if(state.cw.db.records.some(x=>x.address.toLowerCase()===g.address.toLowerCase())){toast('Already in the Database.');return}state.cw.db.records.unshift({id:cwId('DB'),list:'Owners',colour:'',address:g.address,suburb:g.suburb,type:'House',beds:0,baths:0,land:'',lastSold:'',owner:'Owner unknown',mobile:'',email:'',owner2:'',mobile2:'',email2:'',temp:g.signal==='Looks like a mover'?'Warm':'Cold',looking:'Unknown',nextCall:'',lastNote:'Garage sale: '+g.note,dnc:false,permission:'No evidence',market:''});cwPersist('Added to the Database without owner details.')});
